def load() -> pd.DataFrame:
    df = pd.read_csv('/Users/baijiadong/Desktop/chenlab/texera/bin/single-node/examples/datasets/popular-movies-of-imdb/TMDb_updated.csv', nrows=150)
    return df[['id', 'title', 'vote_average']].rename(columns={'id':'Id'})

def process(iris_outliers, iris_movies_join) -> pd.DataFrame:
    outlier_ids = iris_outliers[['Id']].assign(is_outlier=True)
    return iris_movies_join.merge(outlier_ids, on='Id', how='left').fillna({'is_outlier': False})
